MATCH (d:Drug)-[:DrugHasIndication]->(dis:Disorder)
WHERE toLower(d.displayName) = toLower('Ropinirole')
RETURN dis.primaryDomainId AS indicationId, dis.displayName AS indicationName, dis.description AS description;

MATCH (d:Drug)
WHERE toLower(d.displayName) = toLower('Ribavirin')
RETURN d.casNumber AS casNumber, d.primaryDomainId AS drugId, d.displayName AS drugName;

MATCH (d:Drug)-[:DrugHasIndication]->(dis:Disorder)
WHERE toLower(d.displayName) = toLower('Pregabalin')
RETURN dis.primaryDomainId AS disorderId, dis.displayName AS disorderName;

MATCH (dis:Disorder)
WHERE toLower(dis.displayName) = toLower('cystic fibrosis')
RETURN dis.primaryDomainId AS primaryDomainId, dis.displayName AS displayName;

MATCH (d:Disorder)
WHERE toLower(d.displayName) = toLower('Li-Fraumeni syndrome')
RETURN d.primaryDomainId AS disorderId, d.displayName AS disorderName, d.dataSources AS dataSources;

MATCH (dis:Disorder) 
WHERE toLower(dis.displayName) = toLower('Wilson disease') 
RETURN dis.primaryDomainId AS id, dis.displayName AS name, dis.icd10 AS icd10Codes;

MATCH (v:GenomicVariant)-[:VariantAffectsGene]->(g:Gene {primaryDomainId:'entrez.672'})
WHERE v.variantType = 'SNV'
RETURN g.primaryDomainId AS geneId, g.displayName AS geneName, v.primaryDomainId AS variantId, v.displayName AS variantName, v.variantType, v.position, v.chromosome, v.referenceSequence, v.alternativeSequence;

MATCH (v:GenomicVariant {chromosome:'2', position:47475100})-[:VariantAssociatedWithDisorder]->(d:Disorder)
WHERE d.primaryDomainId = 'mondo.0002032'
RETURN v.primaryDomainId AS variantId, v.displayName AS variantName, v.referenceSequence AS referenceSequence;

MATCH (v:GenomicVariant)-[:VariantAssociatedWithDisorder]->(dis:Disorder)
WHERE v.chromosome = 'X'
RETURN dis.primaryDomainId AS disorderId, dis.displayName AS disorderName;

MATCH (v:GenomicVariant)-[:VariantAffectsGene]->(g:Gene {primaryDomainId:'entrez.2217'})
MATCH (v)-[:VariantAssociatedWithDisorder]->(dis:Disorder)
RETURN v.chromosome AS chromosome, v.position AS position, v.primaryDomainId AS variantId, dis.displayName AS disorderName;

MATCH (v:GenomicVariant)-[:VariantAssociatedWithDisorder]->(dis:Disorder)
WHERE v.variantType = 'duplication'
RETURN dis.primaryDomainId AS disorderId, dis.displayName AS disorderName;
